import { Pool } from "pg";

export interface Parcel {
  id: string;
  shipmentId: string;
  weightGrams: number;
  trackingNumber: string | null;
  status: "pending" | "labelled" | "in_transit" | "delivered";
}

export class ParcelRepository {
  constructor(private readonly pool: Pool) {}

  async shipmentExists(shipmentId: string, merchantId: string): Promise<boolean> {
    const r = await this.pool.query(
      "SELECT 1 FROM shipments WHERE id = $1 AND merchant_id = $2",
      [shipmentId, merchantId]
    );
    return r.rowCount === 1;
  }

  async listByShipment(shipmentId: string): Promise<Parcel[]> {
    const r = await this.pool.query(
      "SELECT id, shipment_id, weight_grams, tracking_number, status FROM parcels WHERE shipment_id = $1 ORDER BY id",
      [shipmentId]
    );
    return r.rows.map(toParcel);
  }

  async findById(parcelId: string): Promise<Parcel | null> {
    const r = await this.pool.query(
      "SELECT id, shipment_id, weight_grams, tracking_number, status FROM parcels WHERE id = $1",
      [parcelId]
    );
    return r.rowCount ? toParcel(r.rows[0]) : null;
  }

  async insert(shipmentId: string, weightGrams: number): Promise<Parcel> {
    const r = await this.pool.query(
      "INSERT INTO parcels (shipment_id, weight_grams, status) VALUES ($1, $2, 'pending') RETURNING *",
      [shipmentId, weightGrams]
    );
    return toParcel(r.rows[0]);
  }

  async deletePending(parcelId: string): Promise<boolean> {
    const r = await this.pool.query(
      "DELETE FROM parcels WHERE id = $1 AND status = 'pending'",
      [parcelId]
    );
    return r.rowCount === 1;
  }
}

function toParcel(row: any): Parcel {
  return {
    id: row.id,
    shipmentId: row.shipment_id,
    weightGrams: row.weight_grams,
    trackingNumber: row.tracking_number,
    status: row.status,
  };
}

import { Router, Request, Response, NextFunction } from "express";
import { ParcelRepository } from "./parcelRepository";

export function parcelRoutes(repo: ParcelRepository): Router {
  const r = Router({ mergeParams: true });

  r.use(async (req: Request, res: Response, next: NextFunction) => {
    try {
      const ok = await repo.shipmentExists(req.params.shipmentId, res.locals.merchantId);
      if (!ok) return res.status(404).json({ error: "shipment not found" });
      next();
    } catch (e) {
      next(e);
    }
  });

  r.get("/", async (req, res, next) => {
    try {
      res.json({ data: await repo.listByShipment(req.params.shipmentId) });
    } catch (e) {
      next(e);
    }
  });

  r.post("/", async (req, res, next) => {
    try {
      const weight = Number(req.body?.weightGrams);
      if (!Number.isInteger(weight) || weight <= 0 || weight > 70_000) {
        return res.status(422).json({ error: "weightGrams must be an integer between 1 and 70000" });
      }
      const parcel = await repo.insert(req.params.shipmentId, weight);
      res
        .status(201)
        .location(`/shipments/${req.params.shipmentId}/parcels/${parcel.id}`)
        .json(parcel);
    } catch (e) {
      next(e);
    }
  });

  r.get("/:parcelId", async (req, res, next) => {
    try {
      const parcel = await repo.findById(req.params.parcelId);
      if (!parcel) return res.status(404).json({ error: "parcel not found" });
      res.json(parcel);
    } catch (e) {
      next(e);
    }
  });

  r.delete("/:parcelId", async (req, res, next) => {
    try {
      const parcel = await repo.findById(req.params.parcelId);
      if (!parcel || parcel.shipmentId !== req.params.shipmentId) {
        return res.status(404).json({ error: "parcel not found" });
      }
      if (parcel.status !== "pending") {
        return res.status(409).json({ error: `parcel is ${parcel.status}; only pending parcels can be removed` });
      }
      const removed = await repo.deletePending(parcel.id);
      if (!removed) return res.status(409).json({ error: "parcel status changed; retry" });
      res.status(204).end();
    } catch (e) {
      next(e);
    }
  });

  return r;
}

import express from "express";
import { Pool } from "pg";
import { ParcelRepository } from "./parcelRepository";
import { parcelRoutes } from "./parcelRoutes";

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const app = express();
app.use(express.json());

app.use((req, res, next) => {
  const merchantId = req.header("X-Merchant-Id");
  if (!merchantId) return res.status(401).json({ error: "missing merchant" });
  res.locals.merchantId = merchantId;
  next();
});

app.use("/shipments/:shipmentId/parcels", parcelRoutes(new ParcelRepository(pool)));

app.listen(Number(process.env.PORT ?? 8080));

